FUNCTION_BLOCK FB_S14
VAR_INPUT
    Pressure : REAL;
    PumpEnable : BOOL;
    ResetBtn : BOOL;
END_VAR
VAR_OUTPUT
    LowPump : BOOL := FALSE;
    HighPump : BOOL := FALSE;
    ReliefValve : BOOL := FALSE;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ResetBtnLast : BOOL := FALSE;
    HighPumpLatched : BOOL := FALSE;
    FaultLatched : BOOL := FALSE;
    FirstScan : BOOL := TRUE;
    ResetRise : BOOL := FALSE;
    SensorFault : BOOL := FALSE;
END_VAR

(*
    S14；每次调用为一个20 ms扫描周期。

    需求冲突，保留并报告，待审：
    1. C10要求启动阶段输出全为初态；若启动时压力>160或传感器
       越界，则与同周期卸荷及立即保护冲突。
       本实现启动首扫描禁止加载，但不屏蔽卸荷和故障保护。
       因此不能声称对所有启动输入满足C10。
    2. C7未排除禁止加载、故障和卸荷；这些条件下保持HighPump
       输出可能违反停泵要求。安全联锁强制停泵，内部滞回记忆保留。
    3. C2未排除传感器越界；在低端越界的首次扫描，
       若其AlarmLamp指前一扫描输出，则无条件加载与故障停泵冲突。
    4. LTL的X与“当周期”文字存在时序解释差异；
       本实现按本次输入计算本次输出，不额外延迟保护。
    以上冲突不能由单一实现无条件同时满足。
    源码未经过编译profile验证，也未经过逐周期功能测试。
*)

(* 所有扫描均采样按钮，故障期间的边沿不延后使用。 *)
ResetRise := ResetBtn AND NOT ResetBtnLast;
ResetBtnLast := ResetBtn;

SensorFault := (Pressure < REAL#0.5) OR (Pressure > REAL#250.0);

(* 当前故障优先于复位；故障消失后必须出现新的复位上升沿。 *)
IF SensorFault THEN
    FaultLatched := TRUE;
ELSIF FaultLatched AND ResetRise THEN
    FaultLatched := FALSE;
END_IF;

AlarmLamp := FaultLatched;

IF SensorFault THEN
    Status := WORD#16#8D01;
ELSIF FaultLatched THEN
    Status := WORD#16#8D02;
ELSE
    Status := WORD#16#0000;
END_IF;

(* 卸荷独立于允许加载及报警，严格保留160/150边界。 *)
IF Pressure > REAL#160.0 THEN
    ReliefValve := TRUE;
ELSIF Pressure < REAL#150.0 THEN
    ReliefValve := FALSE;
END_IF;

(* 高压泵的内部投入记忆仅在压力低于100时撤销。
   禁止加载、报警或卸荷只禁止实际泵输出。 *)
IF Pressure < REAL#100.0 THEN
    HighPumpLatched := FALSE;
END_IF;

(* 默认停泵；只有全部允许条件成立才加载。 *)
LowPump := FALSE;
HighPump := FALSE;

IF NOT FirstScan
   AND PumpEnable
   AND NOT AlarmLamp
   AND NOT ReliefValve THEN

    IF Pressure >= REAL#140.0 THEN
        HighPumpLatched := TRUE;
    END_IF;

    LowPump := Pressure < REAL#120.0;
    HighPump := HighPumpLatched;
END_IF;

(* 显式最终安全联锁，确保卸荷阀与两泵互斥。 *)
IF SensorFault OR AlarmLamp OR ReliefValve OR NOT PumpEnable THEN
    LowPump := FALSE;
    HighPump := FALSE;
END_IF;

FirstScan := FALSE;
END_FUNCTION_BLOCK
